export async function signIn(page, email, password) {
    await page.getByRole("textbox", { name: "Email" }).fill(email);
    await page.getByRole("textbox", { name: "Password" }).fill(password);
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse("**/auth/login**");
    await page.getByRole("button", { name: "Sign In" }).click();
    return await responsePromise;
}

export async function dismissProjectOwnerReminder(page) {
    await page.getByRole("button", { name: "Remind Later" }).click();
}

export async function openFieldsAndLayout(page, url) {
    await page.goto(url);
    await page.waitForLoadState('networkidle');
    await page.locator('.fields-management .field-select').first().waitFor({ state: "visible", timeout: 10000 });
}

export async function beginFieldDrag(page, startX, startY, endX, endY) {
    await page.mouse.move(startX, startY);
    await page.mouse.down();
    await page.mouse.move(endX, endY, { steps: 30 });
}

export async function dropDraggedField(page) {
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse("**/fields/**");
    await page.mouse.up();
    return await responsePromise;
}

export async function dragFieldWithinOwnRow(page, startX, startY, endX, endY) {
    await page.mouse.move(startX, startY);
    await page.mouse.down();
    await page.mouse.move(endX, endY, { steps: 10 });
    await page.mouse.up();
    await page.waitForTimeout(3000);
}

export async function reloadFieldsAndLayout(page) {
    await page.reload();
    await page.waitForLoadState('networkidle');
    await page.locator('.fields-management .field-select').first().waitFor({ state: "visible", timeout: 10000 });
}
